// Auto-generated from world-atlas's land-50m.json (see scratch generate.js
// used to produce it). Packed bitmap: LAND_LAT_STEPS rows (north to south) x
// LAND_LON_STEPS cols (west to east), 1 bit per cell, 1 = land. Decoded once
// into a Uint8Array and looked up by lat/lon — keeps the actual geo library
// out of the client bundle entirely.
export const LAND_LAT_STEPS = 90;
export const LAND_LON_STEPS = 180;
export const LAND_MASK_B64 =
  "";

let cachedBitmap: Uint8Array | null = null;

function bitmap(): Uint8Array {
  if (cachedBitmap) return cachedBitmap;
  const binary = atob(LAND_MASK_B64);
  const arr = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) arr[i] = binary.charCodeAt(i);
  cachedBitmap = arr;
  return arr;
}

/** Nearest-cell land lookup for a given lat/lon in degrees. */
export function isLand(latDeg: number, lonDeg: number): boolean {
  const row = Math.min(LAND_LAT_STEPS - 1, Math.max(0, Math.floor(((90 - latDeg) / 180) * LAND_LAT_STEPS)));
  const normalizedLon = ((lonDeg + 180) % 360 + 360) % 360;
  const col = Math.min(LAND_LON_STEPS - 1, Math.floor((normalizedLon / 360) * LAND_LON_STEPS));
  const bitIndex = row * LAND_LON_STEPS + col;
  const bytes = bitmap();
  return (bytes[bitIndex >> 3] & (1 << (bitIndex % 8))) !== 0;
}
